const input = $input.first().json;
const job = input.job ?? input;
if (job.kind !== 'generate_plan' || !job.id || !job.client_id || !job.leaseToken) throw new Error('Contrato generate_plan v1 invalido');
return [{ json: { schemaVersion: 1, job } }];

const job = $('Validar trabajo').first().json.job;
const context = $input.first().json;
const raw = job.payload?.planItems ?? job.payload?.aiOutput;
if (!Array.isArray(raw) || raw.length === 0) throw new Error('Inserta los nodos de fuentes/IA y entrega payload.planItems');
const planItems = raw.map((item, index) => {
  if (!item || typeof item.title !== 'string' || !item.title.trim()) throw new Error(`planItems[${index}].title es obligatorio`);
  if (item.plannedAt != null && Number.isNaN(Date.parse(item.plannedAt))) throw new Error(`planItems[${index}].plannedAt no es ISO-8601`);
  const calendarId = item.calendarId ?? job.target_id;
  if (!calendarId) throw new Error(`planItems[${index}].calendarId es obligatorio`);
  return { ...item, calendarId, title: item.title.trim(), keywords: Array.isArray(item.keywords) ? item.keywords : [], entities: Array.isArray(item.entities) ? item.entities : [], sourceContext: { ...(item.sourceContext ?? {}), workflowVersion: 1, timezone: context.settings?.timezone ?? 'Europe/Madrid' }, sourceKey: item.sourceKey ?? `inficon-plan:${job.id}:${index}` };
});
return [{ json: { schemaVersion: 1, clientId: job.client_id, status: 'succeeded', planItems, result: { count: planItems.length, workflowVersion: 1 }, leaseToken: job.leaseToken, jobId: job.id } }];
